const crypto = require('node:crypto');
const workos = require('./_workos');
const TIERS=Object.freeze({starter:{env:'STRIPE_PRICE_STARTER',amount:499},pro:{env:'STRIPE_PRICE_PRO',amount:1999},platinum:{env:'STRIPE_PRICE_PLATINUM',amount:9999}});
class BillingError extends Error {constructor(status,code){super(code);this.status=status;this.code=code;}}
function mode(){const v=process.env.STRIPE_BILLING_MODE||'test';if(!['test','live'].includes(v))throw new BillingError(503,'billing_unconfigured');return v;}
