async function authenticated(req,res){if(!workos.isConfigured())throw new BillingError(503,'auth_unconfigured');const user=await workos.currentUser(req,res);if(!user?.id)throw new BillingError(401,'auth_required');return user;}
async function member(db,userId){await db.query('INSERT INTO rachel_billing_members(user_id,billing_mode) VALUES($1,$2) ON CONFLICT DO NOTHING',[userId,mode()]);return(await db.query('SELECT * FROM rachel_billing_members WHERE user_id=$1 AND billing_mode=$2 FOR UPDATE',[userId,mode()])).rows[0];}
