function subscriptionId(o){return id(o.subscription||o.parent?.subscription_details?.subscription);}
function priceValid(p,t){return!!p&&p.active===true&&p.currency==='usd'&&p.unit_amount===TIERS[t]?.amount&&p.recurring?.interval==='month'&&p.recurring.interval_count===1;}
async function checkout(req,res){
 if(req.method!=='POST')throw new BillingError(405,'method_not_allowed');sameOrigin(req);const user=await authenticated(req,res),body=req.body||{},tier=body.tier,attempt=String(body.attempt||'').toLowerCase();
