function configured(){return process.env.RACHEL_ENABLE_CHAT==='true'&&!!process.env.OPENROUTER_API_KEY;}
async function answer(message){
 if(!configured())throw Error('Chat is not enabled.');
 const model=process.env.OPENROUTER_MODEL||'openrouter/free';
 if(model!=='openrouter/free'&&(!model.endsWith(':free')||model.startsWith('openrouter/')))throw Error('Only a specific free model or the free-model router is allowed.');
 const r=await fetch('https://openrouter.ai/api/v1/chat/completions',{method:'POST',signal:AbortSignal.timeout(20000),headers:{Authorization:'Bearer '+process.env.OPENROUTER_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({model,max_tokens:512,provider:{zdr:true,allow_fallbacks:false,max_price:{prompt:0,completion:0,request:0,image:0}},messages:[{role:'system',content:'You are Rachel, an educational real-estate assignment coach. Verify assumptions, ask for missing deal facts, never fabricate comparable sales or laws, recommend qualified local counsel for contracts. Be concise.'},{role:'user',content:message}]})});
 if(!r.ok)throw Error('Coaching provider unavailable.');const d=await r.json();const content=d.choices?.[0]?.message?.content;if(typeof content!=='string'||!content.trim())throw Error('Coaching provider returned no answer.');return content.trim();
}
