api/_cors.js:
module.exports = function withCors(handler) {
  return async function (req, res) {
    const origin = require('./_workos').publicUrl();
    res.setHeader('Vary','Origin');
    if(req.headers?.origin && req.headers.origin !== new URL(origin).origin) return res.status(403).json({error:'Origin not allowed'});
    res.setHeader("Access-Control-Allow-Origin", new URL(origin).origin);
    res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
    res.setHeader("Access-Control-Max-Age", 86400);
    res.setHeader('Cache-Control','no-store');
    if (req.method === "OPTIONS") return res.status(204).end();
    return handler(req, res);
  };
};

