const {Pool}=require('pg');let db;
function pool(){if(!process.env.DATABASE_URL)throw Error('Member storage unavailable');if(!db)db=new Pool({connectionString:process.env.DATABASE_URL,max:3,connectionTimeoutMillis:5000,idleTimeoutMillis:10000});return db;}
