const crypto = require('node:crypto');
const workos = require('./_workos');
const COOKIE = '__Host-rachel-oauth';
function key() { return crypto.createHash('sha256').update(workos.env('WORKOS_COOKIE_PASSWORD')).digest(); }
function cookie(value, age=600) { return `${COOKIE}=${value}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${age}`; }
function begin() {
  const state=crypto.randomBytes(32).toString('base64url'), verifier=crypto.randomBytes(32).toString('base64url');
  const iv=crypto.randomBytes(12), cipher=crypto.createCipheriv('aes-256-gcm',key(),iv);
  const data=Buffer.concat([cipher.update(JSON.stringify({state,verifier,created:Date.now()})),cipher.final()]);
  return {state,verifier,challenge:crypto.createHash('sha256').update(verifier).digest('base64url'),cookie:cookie(Buffer.concat([iv,cipher.getAuthTag(),data]).toString('base64url'))};
}
function verify(req,state) {
  try {
    const value=(req.headers?.cookie||'').split(';').map(x=>x.trim()).find(x=>x.startsWith(COOKIE+'='));
    const b=Buffer.from(value.slice(COOKIE.length+1),'base64url');
    const decipher=crypto.createDecipheriv('aes-256-gcm',key(),b.subarray(0,12));decipher.setAuthTag(b.subarray(12,28));
    const data=JSON.parse(Buffer.concat([decipher.update(b.subarray(28)),decipher.final()]).toString());
    if(typeof state!=='string'||typeof data.state!=='string'||Date.now()-data.created>600000||Date.now()<data.created) return null;
    const a=Buffer.from(state), s=Buffer.from(data.state);
    return a.length===s.length&&crypto.timingSafeEqual(a,s)?data.verifier:null;
  } catch { return null; }
}
module.exports={begin,verify,clear:()=>cookie('',0)};

