    const address = document.getElementById('dealzAddress').value.trim() || 'Unspecified property';
    const assessment = purchase && purchase <= mao ? 'The entered contract price is within this conservative framework.' : 'The entered contract price is above this conservative framework or incomplete.';
    result.insertAdjacentHTML('afterend', `<p class="dealz-summary"><strong>${address}:</strong> ${assessment} The $${fee.toLocaleString()} fee is a planning target, not a guarantee. Verify every input before making or marketing an offer.</p>`);
  }

  function syncAvatar() {
    const stage = document.querySelector('.avatar-stage');
    const status = document.getElementById('voiceStatus');
    if (!stage || !status) return;
    const update = () => {
      const text = status.textContent.toLowerCase();
      stage.classList.toggle('is-listening', text.includes('listening'));
      stage.classList.toggle('is-thinking', text.includes('thinking') || text.includes('reviewing'));
      stage.classList.toggle('is-speaking', text.includes('speaking'));
    };
    new MutationObserver(update).observe(status, { childList: true, characterData: true, subtree: true });
    update();
  }

  addAnalyzer();
  syncAvatar();
})();

