/* LiveKit "Talk live" overlay — matches the Rachel teal theme. */
.livekit-fab {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 60;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 20px;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(135deg, #0a8f95, #087b80);
