.livekit-fab-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: #7dffcf; box-shadow: 0 0 0 0 rgba(125, 255, 207, 0.7);
  animation: livekit-pulse 1.8s infinite;
}
@keyframes livekit-pulse {
  0% { box-shadow: 0 0 0 0 rgba(125, 255, 207, 0.7); }
  70% { box-shadow: 0 0 0 10px rgba(125, 255, 207, 0); }
  100% { box-shadow: 0 0 0 0 rgba(125, 255, 207, 0); }
}

.livekit-panel {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 61;
  width: min(360px, calc(100vw - 32px));
  background: #06201f;
  color: #eafffb;
  border: 1px solid rgba(125, 255, 207, 0.25);
  border-radius: 18px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
  padding: 18px;
  font-family: system-ui, sans-serif;
}
.livekit-panel[hidden] { display: none; }
.livekit-panel-head { display: flex; justify-content: space-between; align-items: flex-start; }
.livekit-panel-head .eyebrow { color: #7dffcf; margin: 0; font-size: 11px; letter-spacing: 0.12em; }
.livekit-panel-head h2 { margin: 2px 0 0; font-size: 17px; }
.livekit-close {
  background: transparent; border: 0; color: #9fd9d2; font-size: 22px; line-height: 1; cursor: pointer;
}
.livekit-status {
  margin: 14px 0 10px; padding: 10px 12px; border-radius: 10px;
  background: rgba(255, 255, 255, 0.06); font-size: 14px;
}
.livekit-status.connecting { background: rgba(255, 196, 0, 0.15); color: #ffe08a; }
.livekit-status.connected { background: rgba(125, 255, 207, 0.15); color: #7dffcf; }
.livekit-status.error { background: rgba(255, 99, 99, 0.15); color: #ffb3b3; }
.livekit-controls { display: flex; gap: 10px; margin-top: 6px; }
.livekit-controls button {
