.livekit-controls .primary { background: #0a8f95; color: #fff; }
.livekit-controls .primary:disabled { opacity: 0.5; cursor: not-allowed; }
.livekit-controls .secondary { background: rgba(255, 255, 255, 0.12); color: #eafffb; }
.livekit-controls .secondary:disabled { opacity: 0.4; cursor: not-allowed; }
.livekit-note { margin: 12px 0 0; font-size: 12px; color: #9fd9d2; }
.livekit-audio { margin-top: 10px; }
.livekit-audio[hidden] { display: none; }
.livekit-audio audio { width: 100%; }

