 const apply=()=>{if(!root||!state)return;root.querySelectorAll('input[data-day]').forEach(x=>x.checked=state.completed_days.includes(Number(x.dataset.day)));document.getElementById('progressFill').style.width=(state.completed_days.length/30*100)+'%';document.getElementById('progressText').textContent=state.completed_days.length+' / 30 complete';};
 let saving=false,dirty=false;
 async function save(){dirty=true;if(saving)return;saving=true;while(dirty){dirty=false;const version=revision;try{const next=await request('POST',{completedDays:state.completed_days,orientationCompleted:state.orientation_completed,schedule:state.schedule});if(version===revision){state=next;status.textContent='Saved to your member account.';}}catch(e){status.textContent=e.message+' Changes remain unsaved.';dirty=false;}}saving=false;}
