const {test}=require('node:test');const assert=require('node:assert/strict');const oauth=require('../api/_oauth');const store=require('../api/_member-store');
test('OAuth state binds cookie, expires and rejects tampering',()=>{process.env.WORKOS_COOKIE_PASSWORD='a'.repeat(40);const f=oauth.begin();const req={headers:{cookie:f.cookie.split(';')[0]}};assert.equal(oauth.verify(req,f.state),f.verifier);assert.equal(oauth.verify(req,'other'),null);assert.equal(oauth.verify({headers:{}},f.state),null);assert.equal(oauth.verify({headers:{cookie:req.headers.cookie+'a'}},f.state),null);const original=Date.now;Date.now=()=>original()+601000;try{assert.equal(oauth.verify(req,f.state),null);}finally{Date.now=original;}});
test('member inputs reject impossible days/times/timezones',()=>{assert.equal(store.validProgress([1,30]),true);for(const x of [[0],[31],[1,1],['1'],null])assert.equal(store.validProgress(x),false);assert.throws(()=>store.schedule({time:'25:00',timezone:'America/New_York'}));assert.throws(()=>store.schedule({time:'09:00',timezone:'wrong'}));assert.deepEqual(store.schedule({time:'09:00',timezone:'America/New_York'}),{time:'09:00',timezone:'America/New_York',durationMinutes:5,deliveryStatus:'not_enabled'});});

test/release.test.js:
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { handler } = require('../netlify/functions/api');
const call = (path, method = 'GET', body = '') => handler({ path: '/api/' + path, httpMethod: method, headers: { 'content-type': 'application/json', host: 'attacker.invalid' }, body });

test('voice stays closed even when legacy bypass is set', async () => {
  process.env.LIVEKIT_API_KEY = 'test'; process.env.LIVEKIT_API_SECRET = 'test';
  process.env.LIVEKIT_URL = 'wss://test.invalid'; process.env.LIVEKIT_REQUIRE_AUTH = 'false';
  delete process.env.WORKOS_API_KEY;
  const response = await call('livekit/token', 'POST', '{}');
  assert.equal(response.statusCode, 503);
  assert.equal(JSON.parse(response.body).code, 'auth_unconfigured');
  const status = JSON.parse((await call('livekit/status')).body);
  assert.equal(status.requiresAuth, true);
  assert.equal(status.authConfigured, false);
});
test('short cookie secret is never accepted as configured auth', () => {
  process.env.WORKOS_API_KEY = 'test'; process.env.WORKOS_CLIENT_ID = 'test';
  process.env.WORKOS_COOKIE_PASSWORD = 'short';
  assert.equal(require('../api/_workos').isConfigured(), false);
  delete process.env.WORKOS_API_KEY;
});
test('missing auth remains honest and does not redirect off-site', async () => {
  const response = await call('auth/login');
  assert.equal(response.statusCode, 503);
  assert.equal(JSON.parse(response.body).code, 'auth_unconfigured');
});
test('adapter rejects malformed, excessive and unknown requests', async () => {
  assert.equal((await call('chat', 'POST', '{')).statusCode, 400);
  assert.equal((await call('chat', 'POST', 'x'.repeat(17000))).statusCode, 413);
  assert.equal((await call('missing')).statusCode, 404);
});
test('checkout retains tier rejection after authentication and cannot start without auth', async () => {
  delete process.env.STRIPE_SECRET_KEY;
  const workos=require('../api/_workos'),configured=workos.isConfigured,user=workos.currentUser;
  workos.isConfigured=()=>true;workos.currentUser=async()=>({id:'test-member'});
  const origin={...{ 'content-type':'application/json' },origin:'https://rachelfindsdealz.site'};
  try {const response=await handler({path:'/api/checkout',httpMethod:'POST',headers:origin,body:'{"tier":"unknown"}'});assert.equal(response.statusCode,400);assert.equal(JSON.parse(response.body).code,'unknown_tier');}
  finally {workos.isConfigured=configured;workos.currentUser=user;}
  delete process.env.WORKOS_API_KEY;
  const response=await handler({path:'/api/checkout',httpMethod:'POST',headers:origin,body:'{"tier":"starter"}'});
  assert.equal(response.statusCode,503);assert.equal(JSON.parse(response.body).code,'auth_unconfigured');
});

database/billing.sql:
BEGIN;
CREATE TABLE IF NOT EXISTS rachel_billing_members (
 user_id text NOT NULL,billing_mode text NOT NULL CHECK(billing_mode IN ('test','live')),
 customer_id text,customer_operation_started timestamptz,subscription_id text,status text NOT NULL DEFAULT 'unsubscribed',tier text,
 blocked boolean NOT NULL DEFAULT false,access_until timestamptz NOT NULL DEFAULT to_timestamp(0),
 updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,billing_mode),UNIQUE(customer_id,billing_mode)
);
ALTER TABLE rachel_billing_members ADD COLUMN IF NOT EXISTS customer_operation_started timestamptz;
CREATE TABLE IF NOT EXISTS rachel_checkout_attempts (
 user_id text NOT NULL,billing_mode text NOT NULL,attempt_id uuid NOT NULL,tier text NOT NULL,
 session_id text,url text,expires_at timestamptz NOT NULL,
 PRIMARY KEY(user_id,billing_mode,attempt_id),UNIQUE(session_id,billing_mode),
 FOREIGN KEY(user_id,billing_mode) REFERENCES rachel_billing_members(user_id,billing_mode)
);
ALTER TABLE rachel_checkout_attempts ALTER COLUMN session_id DROP NOT NULL;
ALTER TABLE rachel_checkout_attempts ALTER COLUMN url DROP NOT NULL;
CREATE TABLE IF NOT EXISTS rachel_billing_events (
 event_id text NOT NULL,billing_mode text NOT NULL,event_type text NOT NULL,
 accepted_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,PRIMARY KEY(event_id,billing_mode)
);
CREATE TABLE IF NOT EXISTS rachel_usage (
 user_id text NOT NULL,billing_mode text NOT NULL,usage_date date NOT NULL,feature text NOT NULL,
 used integer NOT NULL CHECK(used>0),PRIMARY KEY(user_id,billing_mode,usage_date,feature),
 FOREIGN KEY(user_id,billing_mode) REFERENCES rachel_billing_members(user_id,billing_mode)
);
COMMIT;
